import re, unicodedata
from pathlib import Path

def norm(s):
    s = unicodedata.normalize("NFKD", s or "")
    s = "".join(c for c in s if not unicodedata.combining(c)).lower()
    return re.sub(r"[^a-z0-9]+", "", s)

def split_fm(txt):
    if txt.startswith("---"):
        m = re.match(r"^---\s*\n(.*?)\n---\s*\n?(.*)$", txt, re.S)
        if m:
            return m.group(1), m.group(2)
    return "", txt

def body(root):
    out = {}
    for p in Path(root).rglob("*.md"):
        rel = p.relative_to(root)
        if any(part.startswith("_") for part in rel.parts):
            continue
        try:
            txt = p.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        fm, bd = split_fm(txt)
        out[str(rel)] = (norm(bd).strip(), len(bd))
    return out

cur = body("data/biblioteca")
b1  = body("/tmp/biblioteca-backup-pre-higienizacao")
b2  = body("/tmp/biblioteca-backup-pre-normalizacao")

def audit(label, b):
    print(f"########## {label}")
    cur_by_body = {}
    for f,(nb,ln) in cur.items():
        cur_by_body.setdefault(nb, []).append((f,ln))
    exact = 0; contained = 0; lost = []
    for f,(nb,ln) in b.items():
        if nb in cur_by_body:
            exact += 1
            continue
        # procura um atual que contenha o corpo do backup (prefixo) ou vice-versa
        hit = None
        for nb2,(f2,ln2) in cur.items():
            if not nb2: continue
            if len(nb) < 200 or len(nb2) < 200:
                if nb2 == nb: hit=f2; break
                continue
            if nb2.startswith(nb[:2000]) or nb.startswith(nb2[:2000]):
                hit = f2; break
        if hit:
            contained += 1
        else:
            lost.append((f, ln))
    print(f"  corpos EXATOS presentes hoje      : {exact}")
    print(f"  corpos局部/localizados por prefixo : {contained}")
    print(f"  corpos NAO localizados             : {len(lost)}")
    lost.sort(key=lambda x:-x[1])
    tot = sum(x[1] for x in lost)
    print(f"  bytes em corpo nao localizado      : {tot:,}")
    for f,ln in lost[:30]:
        print(f"     SEM PAR: {ln:>9,}  {f}")
    print()

