#!/usr/bin/env python3
"""VALIDACAO FORENSE: cobertura de conteudo por chunk fingerprint.

Para cada arquivo do backup, fingerprinta o corpo em chunks de 32KB.
Depois mede, para cada arquivo atual, quantos chunks do backup ele cobre.
Se a cobertura de um arquivo do backup = 100% (por algum arquivo atual),
o conteudo NAO foi perdido (so mudou de nome/corpo limpo).
"""
import re, hashlib, json, os
from pathlib import Path
from collections import defaultdict

CHUNK = 32 * 1024

def split_fm(txt):
    if txt.startswith("---"):
        m = re.match(r"^---\s*\n(.*?)\n---\s*\n?(.*)$", txt, re.S)
        if m: return m.group(1), m.group(2)
    return "", txt

def chunks_of(bd):
    b = bd.encode("utf-8", "replace")
    if not b: return []
    return [hashlib.sha256(b[i:i+CHUNK]).hexdigest() for i in range(0, len(b), CHUNK)]

def collect(root):
    out = {}
    for p in Path(root).rglob("*.md"):
        rel = p.relative_to(root)
        if any(part.startswith("_") for part in rel.parts): continue
        try: txt = p.read_text(encoding="utf-8", errors="replace")
        except OSError: continue
        fm, bd = split_fm(txt)
        out[str(rel)] = {"fm": fm, "bd": bd, "chunks": chunks_of(bd), "len": len(bd)}
    return out

roots = {
    "cur": "data/biblioteca",
    "b1": "/tmp/biblioteca-backup-pre-higienizacao",
    "b2": "/tmp/biblioteca-backup-pre-normalizacao",
}
data = {}
for k, r in roots.items():
    data[k] = collect(r)
    print(k, len(data[k]), flush=True)

# indice: chunk -> lista de (set, arquivo)
chunk_index = defaultdict(list)
for k in ("cur","b1","b2"):
    for f, d in data[k].items():
        for c in set(d["chunks"]):
            chunk_index[c].append((k, f))

def coverage(bk, f):
    """melhor cobertura: um unico arquivo atual que cobre X% dos chunks do backup"""
    d = data[bk][f]
    cs = d["chunks"]
    if not cs: return 1.0, None
    cnt = defaultdict(int)
    for c in cs:
        for (k, g) in chunk_index.get(c, ()):
            if k == "cur": cnt[g] += 1
    best, bestf = 0.0, None
    for g, n in cnt.items():
        pct = n / len(cs)
        if pct > best: best, bestf = pct, g
    return best, bestf

res = {}
for bk in ("b1","b2"):
    rows = []
    for f, d in data[bk].items():
        cov, match = coverage(bk, f)
        rows.append({"file": f, "len": d["len"], "cov": cov, "match": match,
                     "in_cur_name": f in data["cur"]})
    res[bk] = rows
    full = [r for r in rows if r["cov"] >= 0.999]
    part = [r for r in rows if 0.5 <= r["cov"] < 0.999]
    lost = [r for r in rows if r["cov"] < 0.5]
    print(f"\n===== {bk}: total {len(rows)}")
    print(f"  conteudo 100% presente em algum arquivo atual : {len(full)}  ({sum(r['len'] for r in full):,} bytes)")
    print(f"  conteudo PARCIAL (50-99%)                     : {len(part)}  ({sum(r['len'] for r in part):,} bytes)")
    print(f"  conteudo AUSENTE (<50%)                       : {len(lost)}  ({sum(r['len'] for r in lost):,} bytes)")
    for r in sorted(lost, key=lambda x: -x["len"])[:40]:
        print(f"     AUSENTE {r['len']:>10,}B cov={r['cov']:.2%}  {r['file']}")
    for r in sorted(part, key=lambda x: -x["len"])[:20]:
        print(f"     PARCIAL {r['len']:>10,}B cov={r['cov']:.2%} -> {r['match']}  {r['file']}")

json.dump(res, open("/tmp/val_chunk.json","w"))
print("\nOK")
PY
